package net.minecraft.world;import net.minecraft.world.item.ItemStack;import net.minecraft.world.entity.player.Player;public class SimpleContainer{protected ItemStack[] items;public SimpleContainer(int size){items=new ItemStack[size];java.util.Arrays.fill(items,ItemStack.EMPTY);}public int getContainerSize(){return items.length;}public ItemStack getItem(int i){return items[i];}public void setItem(int i,ItemStack s){items[i]=s;setChanged();}public void setChanged(){}public boolean canPlaceItem(int i,ItemStack s){return true;}public boolean stillValid(Player p){return true;}public boolean add(ItemStack s){for(int i=0;i<items.length;i++)if(items[i].isEmpty()){items[i]=s.copy();s.setCount(0);return true;}return false;}}